    result: StacktraceLinkOutcome = {
        "source_url": None,
        "error": None,
        "current_config": None,
        "iteration_count": 0,
        "is_munged": False,
    }
    for config in configs:
        outcome: ReposityLinkOutcome = {}
        munging_outcome: ReposityLinkOutcome = {}

