        result = await self.client(functions.updates.GetDifferenceRequest(pts=pts - 1, date=date, qts=0))
    if isinstance(result, (types.updates.Difference, types.updates.DifferenceSlice, types.updates.ChannelDifference, types.updates.ChannelDifferenceTooLong)):
        self.update._entities.update({utils.get_peer_id(x): x for x in itertools.chain(result.users, result.chats)})

