def upload_submit_async(self, **kwargs):
    if 'validate' in kwargs:
        fields = json.loads(kwargs['validate'])
        err = {}
        for field in fields:
            if field in tmpl_context.form_errors:
                err[field] = tmpl_context.form_errors[field]
        data = dict(valid=len(err) == 0, err=err)
    elif len(tmpl_context.form_errors) != 0:
        data = dict(success=False)
    else:
        kwargs.setdefault('name')
        kwargs.setdefault('tags')
        media_obj = self._save_media_obj(kwargs['name'], kwargs['email'], kwargs['title'], kwargs['description'], kwargs['tags'], kwargs['file'])
        email.send_media_notification(media_obj)
        data = dict(success=True, redirect=url_for(action='upload_success'))
    response.headers['Content-Type'] = helpers.best_json_content_type()
    return json.dumps(data)

