    if nick == "msbobBot":
        subprocess.check_output(["sudo", "-n", "/home/peter/ircbot/scripts/fixperms.sh"], stderr=subprocess.STDOUT)
    return subprocess.check_output(['git', 'pull'], cwd=srcdir, stderr=subprocess.STDOUT).decode().splitlines()[-1]

def free_energy(self, v_sample):
    h_mean = T.nnet.sigmoid(T.dot(v_sample, self.W) + self.hbias)
    #TODO: make sure log(sigmoid) is optimized to something stable!
    return -T.sum(T.log(1.0001-h_mean)) - T.sum(T.dot(v_sample, self.vbias))

