def get_make_environment_vars():
    if 'PYODIDE_ROOT' in os.environ:
        PYODIDE_ROOT = Path(os.environ['PYODIDE_ROOT'])
    else:
        PYODIDE_ROOT = search_pyodide_root(os.getcwd())
    environment = {}
    result = subprocess.run(['make', '-f', str(PYODIDE_ROOT / 'Makefile.envs'), '.output_vars'], capture_output=True, text=True)
    for line in result.stdout.splitlines():
        equalPos = line.find('=')
        if equalPos != -1:
            varname = line[0:equalPos]
            value = line[equalPos + 1:]
            value = value.strip("'").strip()
            environment[varname] = value
    return environment

