def do_node_deploy(task, conductor_id=None, configdrive=None):
    node = task.node
    utils.del_secret_token(node)
    try:
        if configdrive:
            if isinstance(configdrive, dict):
                configdrive = utils.build_configdrive(node, configdrive)
            _store_configdrive(node, configdrive)
    except (exception.SwiftOperationError, exception.ConfigInvalid) as e:
        with excutils.save_and_reraise_exception():
            utils.deploying_error_handler(task, 'Error while uploading the configdrive for %(node)s to Swift' % {'node': node.uuid}, _('Failed to upload the configdrive to Swift. Error: %s') % e, clean_up=False)
    except db_exception.DBDataError as e:
        with excutils.save_and_reraise_exception():
            node.obj_reset_changes()
            utils.deploying_error_handler(task, 'Error while storing the configdrive for %(node)s into the database: %(err)s' % {'node': node.uuid, 'err': e}, _('Failed to store the configdrive in the database. %s') % e, clean_up=False)
    except Exception as e:
        with excutils.save_and_reraise_exception():
            utils.deploying_error_handler(task, 'Unexpected error while preparing the configdrive for node %(node)s' % {'node': node.uuid}, _('Failed to prepare the configdrive. Exception: %s') % e, traceback=True, clean_up=False)
    try:
        task.driver.deploy.prepare(task)
    except exception.IronicException as e:
        with excutils.save_and_reraise_exception():
            utils.deploying_error_handler(task, 'Error while preparing to deploy to node %(node)s: %(err)s' % {'node': node.uuid, 'err': e}, _('Failed to prepare to deploy: %s') % e, clean_up=False)
    except Exception as e:
        with excutils.save_and_reraise_exception():
            utils.deploying_error_handler(task, 'Unexpected error while preparing to deploy to node %(node)s' % {'node': node.uuid}, _('Failed to prepare to deploy. Exception: %s') % e, traceback=True, clean_up=False)
    try:
        conductor_steps.set_node_deployment_steps(task)
    except exception.InstanceDeployFailure as e:
        with excutils.save_and_reraise_exception():
            utils.deploying_error_handler(task, 'Error while getting deploy steps; cannot deploy to node %(node)s. Error: %(err)s' % {'node': node.uuid, 'err': e}, _('Cannot get deploy steps; failed to deploy: %s') % e)
    do_next_deploy_step(task, 0, conductor_id)

def argRepr(args=(), kwargs={}, max=0):
    if not (type(args) is tuple or type(args) is list):
        raise TypeError('args must be a list or a tuple')
    elif not type(kwargs) is dict:
        raise TypeError('kwargs must be a dict')
    args = list(args)
    s = ''
    if args:
        parts = []
        for arg in args:
            if max and len(arg) > max:
                parts.append('..%s..' % arg[2:max - 2])
            else:
                parts.append(str(arg))
        s += ', '.join(parts)
    if kwargs:
        r = [key + '=' + repr(item) for (key, item) in kwargs.items()]
        if s:
            s += ', '
        s += ', '.join(r)
    return s

