def readTextFromFile(self, fileName=None, encoding=None):
    previousFileName = self._fileName
    fileName = fileName or self._fileName
    try:
        with open(fileName, 'rb') as openfile:
            data = openfile.read()
    except OSError as ex:
        QMessageBox.warning(self, '', str(ex))
        return
    if encoding is None and globalSettings.detectEncoding:
        encoding = self.detectEncoding(data[:2048])
    encoding = encoding or globalSettings.defaultCodec or None
    try:
        text = data.decode(encoding or locale.getpreferredencoding(False))
    except (UnicodeDecodeError, LookupError) as ex:
        QMessageBox.warning(self, '', str(ex))
        return
    if encoding:
        self.editBox.document().setProperty('encoding', encoding)
    self._fileName = fileName
    if previousFileName != self._fileName:
        self.updateActiveMarkupClass()
    self.forceDisableAutoSave = False
    self.editBox.setPlainText(text)
    self.editBox.document().setModified(False)
    self.handleModificationChanged()
    cssFileName = self.getBaseName() + '.css'
    self.cssFileExists = QFile.exists(cssFileName)
    if previousFileName != self._fileName:
        self.fileNameChanged.emit()

def testjob(request, job):
    job = get_restricted_job(request.user, pk=job, request=request)
    data = ResultsView(request, model=TestSuite, table_class=ResultsTable)
    suite_table = ResultsTable(data.get_table_data().filter(job=job))
    failed_definitions = []
    yaml_dict = OrderedDict()
    if TestData.objects.filter(testjob=job).exists():
        testdata = TestData.objects.filter(testjob=job).prefetch_related('actionlevels__testcase', 'actionlevels__testcase__suite')[0]
        if job.status in [TestJob.INCOMPLETE, TestJob.COMPLETE]:
            executed = [{case.action_metadata['test_definition_start']: case.action_metadata.get('success', '')} for case in TestCase.objects.filter(suite__in=TestSuite.objects.filter(job=job)) if case.action_metadata and 'test_definition_start' in case.action_metadata and (case.suite.name == 'lava')]
            submitted = [actiondata.testcase.action_metadata for actiondata in testdata.actionlevels.all() if actiondata.testcase and 'test-runscript-overlay' in actiondata.action_name]
            for item in submitted:
                if executed and {item['name']: item['success']} not in executed:
                    comparison = {}
                    if item['from'] != 'inline':
                        comparison['repository'] = item['repository']
                    comparison['path'] = item['path']
                    comparison['name'] = item['name']
                    comparison['uuid'] = item['success']
                    failed_definitions.append(comparison)
        for data in testdata.attributes.all().order_by('name'):
            yaml_dict[str(data.name)] = str(data.value)
    RequestConfig(request, paginate={'per_page': suite_table.length}).configure(suite_table)
    return render_to_response('lava_results_app/job.html', {'bread_crumb_trail': BreadCrumbTrail.leading_to(testjob, job=job.id), 'job': job, 'job_link': pklink(job), 'suite_table': suite_table, 'metadata': yaml_dict, 'failed_definitions': failed_definitions}, RequestContext(request))

