def write_full_dns_config(zones=None, reverse_zones=None, callback=None, **kwargs):
    if zones is None:
        zones = {}
    if reverse_zones is None:
        reverse_zones = {}
    for (zone_name, zone_data) in zones.items():
        DNSZoneConfig(zone_name).write_config(**zone_data)
    for (zone_name, zone_data) in reverse_zones.items():
        DNSZoneConfig(zone_name).write_config(**zone_data)
    config = DNSConfig(zone_names=list(zones), reverse_zone_names=list(reverse_zones))
    config.write_config(**kwargs)
    if callback is not None:
        callback.delay()

