def _get_done_status(self, generated, batch):
    done_idx = torch.minimum((generated != self.EOS_TOKEN_ID).sum(dim=-1) - batch.prompt_rindex, torch.tensor(self.max_new_tokens) - 1)
    done = torch.zeros(done_idx.numel(), self.max_new_tokens, dtype=torch.bool, device=generated.device)
    done.scatter_(-1, done_idx.unsqueeze(-1), 1)
    return done.unsqueeze(-1)

