def iterTiltPairs(self):
    mics = self.getMicrographs()
    for (micUId, micTId) in mics.iterTiltPairs():
        micU = mics[micUId]
        micT = mics[micTId]
        for (coordU, coordT) in zip(self.iterMicrographCoordinates(micU), self.iterMicrographCoordinates(micT)):
            yield (coordU.getId(), coordT.getId())

