def _visit_partitionable_operation(self, operation_def, upstream_views):
    all_fine_grained_views_available = all((v.fine_grained_view for v in upstream_views))
    prefer_fine_grained_view = any((v.prefer_fine_grained_view for v in upstream_views)) or (all_fine_grained_views_available and operation_def.cache_coder is not None)
    next_hashed_path = self._make_next_hashed_path([v.hashed_path for v in upstream_views], operation_def)
    if all_fine_grained_views_available:
        fine_grained_views = (self._apply_operation_on_fine_grained_view(operation_def, tuple((v.fine_grained_view for v in upstream_views)), next_hashed_path),)
    else:
        fine_grained_views = (None,) * operation_def.num_outputs
    flattened_views = nodes.OperationNode(operation_def, tuple((v.flattened_view for v in upstream_views))).outputs
    assert len(fine_grained_views) == len(flattened_views)
    return tuple((_OptimizationView(prefer_fine_grained_view=prefer_fine_grained_view, flattened_view=flat, fine_grained_view=fine, hashed_path=next_hashed_path) for (flat, fine) in zip(flattened_views, fine_grained_views)))

def _preprocess(features, wires, pad_with, normalize):
    shape = qml.math.shape(features)
    if len(shape) != 1:
        raise ValueError(f'Features must be a one-dimensional tensor; got shape {shape}.')
    n_features = shape[0]
    if pad_with is None and n_features != 2 ** len(wires):
        raise ValueError(f"Features must be of length {2 ** len(wires)}; got length {n_features}. Use the 'pad' argument for automated padding.")
    if pad_with is not None and n_features > 2 ** len(wires):
        raise ValueError(f'Features must be of length {2 ** len(wires)} or smaller to be padded; got length {n_features}.')
    if pad_with is not None and n_features < 2 ** len(wires):
        padding = [pad_with] * (2 ** len(wires) - n_features)
        features = qml.math.concatenate([features, padding], axis=0)
    norm = qml.math.sum(qml.math.abs(features) ** 2)
    if not qml.math.allclose(norm, 1.0, atol=TOLERANCE):
        if normalize or pad_with:
            features = features / np.sqrt(norm)
        else:
            raise ValueError(f"Features must be a vector of length 1.0; got length {norm}.Use 'normalize=True' to automatically normalize.")
    return features

