def _visit_partitionable_operation(self, operation_def, upstream_views):
    (upstream_view,) = upstream_views
    prefer_fine_grained_view = upstream_view.prefer_fine_grained_view or (upstream_view.fine_grained_view and operation_def.cache_coder is not None)
    next_hashed_path = self._make_next_hashed_path([v.hashed_path for v in upstream_views], operation_def)
    fine_grained_views = [self._apply_operation_on_fine_grained_view(operation_def, view.fine_grained_view, next_hashed_path) for view in upstream_views if view.fine_grained_view]
    if len(fine_grained_views) < operation_def.num_outputs:
        fine_grained_views += [None] * (operation_def.num_outputs - len(fine_grained_views))
