def show_widget(self, request, video_url, is_remote, base_state=None):
    (video, create) = models.Video.get_or_create_for_url(video_url)
    video.widget_views_count += 1
    video.save()
    self._maybe_add_video_session(request)
    return_value = {'video_id': video.video_id}
    add_general_settings(request, return_value)
    if request.user.is_authenticated():
        return_value['username'] = request.user.username
    return_value['video_urls'] = [vu.effective_url for vu in video.videourl_set.all()]
    return_value['drop_down_contents'] = self._drop_down_contents(request.user, video)
    if base_state is not None:
        subtitles = self._autoplay_subtitles(request.user, video, base_state.get('language', None), base_state.get('revision', None))
        return_value['subtitles'] = subtitles
    elif is_remote:
        autoplay_language = self._find_remote_autoplay_language(request)
        if autoplay_language is not None:
            subtitles = self._autoplay_subtitles(request.user, video, autoplay_language, None)
            return_value['subtitles'] = subtitles
    return return_value

